#include "midi/MidiDeviceService.h"
#include <algorithm>
namespace jeff::daw {MidiDeviceService::MidiDeviceService(MidiBackend&b,SpscEventQueue<4096>&q):backend(b),queue(q){refresh();}MidiDeviceService::~MidiDeviceService(){for(auto&id:opened)backend.close(id);}void MidiDeviceService::refresh(){current=backend.devices();for(auto&id:selected){auto it=std::find_if(current.begin(),current.end(),[&](auto&d){return d.stableId==id;});if(it==current.end()){if(opened.erase(id))backend.close(id);status[id]=DeviceStatus::disconnected;}else if(!opened.contains(id))openSelected(*it);}for(auto&d:current)if(!selected.contains(d.stableId))status[d.stableId]=DeviceStatus::available;}bool MidiDeviceService::connect(const std::string&id){selected.insert(id);auto it=std::find_if(current.begin(),current.end(),[&](auto&d){return d.stableId==id;});if(it==current.end()){status[id]=DeviceStatus::disconnected;return false;}return openSelected(*it);}void MidiDeviceService::disconnect(const std::string&id){selected.erase(id);if(opened.erase(id))backend.close(id);status[id]=DeviceStatus::available;}std::vector<std::string>MidiDeviceService::selectedDeviceIds()const{return{selected.begin(),selected.end()};}DeviceStatus MidiDeviceService::statusFor(const std::string&id)const{auto it=status.find(id);return it==status.end()?DeviceStatus::disconnected:it->second;}bool MidiDeviceService::openSelected(const DeviceIdentity&d){auto*p=&profiles.match(d);auto ok=backend.open(d.stableId,[this,p](const std::string&,const MidiMessage&m){auto b=p->decode(m,tick++);for(int i=0;i<b.size;++i)queue.push(b.events[i]);});status[d.stableId]=ok?DeviceStatus::connected:DeviceStatus::disconnected;if(ok)opened.insert(d.stableId);return ok;}}
